func workspaceFreshness(ctx context.Context, opts Options, manifest workspaceManifest) ([]workspaceRepoFreshness, error) {
	var result []workspaceRepoFreshness
	for _, repo := range manifest.Repos {
		result = append(result, workspaceRepoFreshnessForRepo(ctx, opts, repo))
	}
	return result, nil
}

func workspaceRepoFreshnessForRepo(ctx context.Context, opts Options, repo workspaceRepo) workspaceRepoFreshness {
	status := workspaceRepoFreshness{RepoKey: repo.RepoKey, Name: repo.Name}
	brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)
	if err != nil {
		status.State = "unsafe"
		status.Detail = err.Error()
		return status
	}
	manifestPath := filepath.Join(brainDir, exportManifestFileName)
	_, manifestErr := os.Stat(manifestPath)
	manifestMissing := os.IsNotExist(manifestErr)
	if manifestErr != nil && !manifestMissing {
		status.State = "unsafe"
		status.Detail = manifestErr.Error()
		return status
	}
	if repo.LocalPathHint == "" {
		if manifestMissing {
			status.State = "missing-brain"
			return status
		}
		status.State = "unknown"
		status.Detail = "no local_path_hint"
		return status
	}
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, repo.LocalPathHint)
	if err != nil {
		status.State = "unsafe"
		status.Detail = err.Error()
		return status
	}
	if !local {
		status.State = "unknown"
		status.Detail = "local_path_hint unavailable"
	})
}

func readerSHA256(r io.Reader) (string, error) {
	hasher := sha256.New()
	if _, err := io.Copy(hasher, r); err != nil {
		return "", err
	}
	return hex.EncodeToString(hasher.Sum(nil)), nil
}

func validateImportedBundle(root, repoKey string) (*exportManifest, error) {
	data, err := os.ReadFile(filepath.Join(root, exportManifestFileName))
	if err != nil {
		return nil, fmt.Errorf("bundle missing manifest: %w", err)
	}
	var manifest exportManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return nil, fmt.Errorf("parse bundle manifest: %w", err)
	}
	symbolsPresent, relationsPresent, err := bundleSemanticCountPresence(data)
	if err != nil {
		return nil, err
	}
	if manifest.RepoKey == "" {
		return nil, errors.New("bundle manifest missing repo_key")
	}
	if !semanticRepoKeyEqual(manifest.RepoKey, repoKey) {
		return nil, fmt.Errorf("bundle repo_key %q does not match current repo %q", manifest.RepoKey, repoKey)
	}
	if manifest.Sources == nil || manifest.Sources.Semantic == nil {
		return nil, errors.New("bundle manifest missing semantic source")
	}
	if err := validateSemanticSchema(manifest.Sources.Semantic.SchemaVersion); err != nil {
		return nil, fmt.Errorf("bundle semantic schema unsupported: %w", err)
	}
	if skew := semanticSchemaMinorSkewWarning(manifest.Sources.Semantic.SchemaVersion); skew != nil {
