// every other cooperative manifest mutation.
func discardManifestThisBuildCannotRewrite(brainDir string) (bool, error) {
	unrewritable := false
	err := withBrainManifestWriteLock(brainDir, func() error {
		return removeCheckedMemoryStateFile(brainDir, exportManifestFileName, "brain manifest", maxManifestBytes, func(data []byte) error {
			version, err := checkedVersionedJSONHeader(data, brainManifestSchemaVersion, "brain manifest")
			if err != nil {
				return err
			}
			// The same range the reader enforces. checkedVersionedJSONHeader only
			// rejects versions newer than this build, so without this a negative
			// or otherwise out-of-range version reaches the delete -- state the
			// reader already calls unsupported, which is exactly the "genuine
			// corruption stays" case above.
			if version < 0 || version > brainManifestSchemaVersion {
				return fmt.Errorf("%s: unsupported brain manifest schema version %d", memoryErrUnsupportedVersion, version)
			}
			var manifest exportManifest
			droppedUnknownFields, decodeErr := decodeVersionedJSONBody(data, &manifest, true)
			if decodeErr != nil {
				return fmt.Errorf("%s: brain manifest cannot be parsed: %w", memoryErrStateCorrupt, decodeErr)
			}
			if !droppedUnknownFields {
				return errManifestRoundTrips
			}
			unrewritable = true
			return nil
		})
	})
	if errors.Is(err, errManifestRoundTrips) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return unrewritable, nil
}

			gitLogRecordSeparator)
	}
	return b.String()
}

// TestWriteBrainManifestRefusesWhatItCannotReadBack pins the writer/reader
// symmetry. readBrainManifest has always capped the manifest at
// maxManifestBytes; the writer had no cap, so an oversized record was written
// successfully and every later read -- status and doctor included -- failed. The
// write must fail instead, and the manifest that was readable a moment ago must
// still be there afterwards.
func TestWriteBrainManifestRefusesWhatItCannotReadBack(t *testing.T) {
	brainDir := t.TempDir()
	good := exportManifest{
		SchemaVersion: brainManifestSchemaVersion,
		RepoKey:       "local/example",
		Sources:       &brainSources{},
	}
	if err := writeBrainManifestAndReadme(brainDir, good); err != nil {
		t.Fatalf("write baseline manifest: %v", err)
	}
	before, err := os.ReadFile(filepath.Join(brainDir, exportManifestFileName))
	if err != nil {
		t.Fatalf("read baseline: %v", err)
	}

	oversized := good
	oversized.Sources = &brainSources{Seed: &seedSourceManifest{
		GeneratedAt:     time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
		HistoryCoverage: coverageFixture(50000),
	}}
	err = writeBrainManifestAndReadme(brainDir, oversized)
	if err == nil {
		t.Fatal("writing a manifest larger than the read bound must fail")
	}
	var bound *readBoundExceededError
	if !errors.As(err, &bound) {
		t.Fatalf("want a read-bound error naming the size, got %v", err)
	}
	// An error the caller cannot act on is only half a refusal.
	if !strings.Contains(err.Error(), "previous manifest") {
		t.Fatalf("refusal does not say the previous manifest survived: %v", err)
	}

	after, err := os.ReadFile(filepath.Join(brainDir, exportManifestFileName))
	if err != nil {
		t.Fatalf("read after refusal: %v", err)
	}
	if string(after) != string(before) {
		t.Fatal("refused write replaced the readable manifest")
	}
	// The real assertion: the brain still works.
	if _, err := loadBrainManifest(brainDir); err != nil {
		t.Fatalf("manifest unreadable after a refused write: %v", err)
	}
}

// TestSeedPrintsEveryWarningNotJustACount pins the one line that tells a user a
// large repository was only partly read. `refresh seed` printed "warnings: 1"
// and stopped, so the whole report of a brain that skipped most of the
// repository was a digit. `refresh sessions` has always printed the text too.
func TestSeedPrintsEveryWarningNotJustACount(t *testing.T) {
	repoDir := seedFixtureRepo(t)
	dataDir := filepath.Join(t.TempDir(), "data")
	cmd := NewRootCommand(Options{
		Version: "test-version",
package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const brainManifestSchemaVersion = 3

// brainManifestMinSchemaVersion is the oldest manifest this build reads.
//
// It is 1 rather than 0 because 0 is not a version anything ever wrote: the
// commit that introduced manifest.json already set schema_version 1, and the
// field carries no `omitempty`, so no build of this tool can emit a manifest
// without one. A manifest reporting 0 is therefore an ABSENT field -- `{}`, a
// hand-edited file, a truncated write -- and not a pre-versioning document to
// adapt. Reading it as "current" was how an empty object passed for a healthy
// brain.
const brainManifestMinSchemaVersion = 1

const (
	brainLockDirName      = "locks"
	brainWriteLockName    = "write.lock"
	brainManifestLockName = "manifest.lock"
	brainPrivacyLockName  = "privacy-side-effect.lock"
	brainDistillLockName  = "distill-pass.lock"
	brainWriteLockTimeout = 10 * time.Second
)

