)

// Only aggregate shape information comes from the cohort. Every value below is
// synthetic. Session metadata is deliberately repeated through the production
// session aliases, as it is in retained manifests.
func TestBrainManifestObservedShapesRoundTrip(t *testing.T) {
 for _, tc := range []struct{name string; branches, sessions, warnings, bytes int}{
  {"session-heavy", 870, 5305, 111, 18569433},
  {"warning-heavy", 389, 2633, 6238, 17220291},
  {"larger-than-default-read-limit", 1800, 20000, 12000, 80 << 20},
 } {
  t.Run(tc.name, func(t *testing.T) {
   dir := t.TempDir()
   source := &sessionSourceManifest{}
   for i:=0; i<tc.branches; i++ { source.Branches = append(source.Branches, exportBranch{Branch: fmt.Sprintf("branch-%d", i), Directory: fmt.Sprintf("sessions/branch-%d", i), SessionCount: 1}) }
   for i:=0; i<tc.sessions; i++ { source.Sessions = append(source.Sessions, exportSession{SessionID: fmt.Sprintf("session-%d", i), Branch: "main", LatestCheckpoint: fmt.Sprintf("%012x", i), TranscriptPath: fmt.Sprintf("sessions/main/session-%d.jsonl", i), Summary: &checkpointSummary{Intent: strings.Repeat("synthetic intent ", 30), Outcome: "synthetic outcome"}, FilesTouched: []string{"internal/example.go"}}) }
   for i:=0; i<tc.warnings; i++ { source.Warnings = append(source.Warnings, fmt.Sprintf("synthetic checkpoint coverage warning %d", i)) }
   manifest := exportManifest{SchemaVersion: brainManifestSchemaVersion, RepoKey: "local/synthetic", Sources: &brainSources{Sessions: source}}
   applySessionSourceAliases(&manifest)
   // Size-match with a known scalar, without introducing unknown fields or
   // actual cohort content. The large case exceeds even defaultMaxReadBytes.
   manifest.BrainVersion = "x"
   normalizeBrainManifest(&manifest)
   data, err := json.MarshalIndent(manifest, "", "  ")
   if err != nil { t.Fatal(err) }
   padding := tc.bytes - len(data) - 1
   if padding < 0 { t.Fatalf("fixture already exceeds target by %d", -padding) }
   manifest.BrainVersion += strings.Repeat("x", padding)
   if err := writeBrainManifestAndReadme(dir, manifest); err != nil { t.Fatal(err) }
   info, err := os.Stat(filepath.Join(dir, exportManifestFileName))
   if err != nil || info.Size() != int64(tc.bytes) { t.Fatalf("size: %v, %v", info, err) }
   for _, reader := range []func(string)(*exportManifest,error){loadBrainManifest, loadBrainManifestForReplace} {
    got, err := reader(dir)
    if err != nil { t.Fatal(err) }
    if !reflect.DeepEqual(got, &manifest) { t.Fatal("manifest records changed during round trip") }
   }
   got, health, issue := inspectBrainManifestHealth(dir)
   if issue != nil || health.State != "current" || len(got.Sessions) != tc.sessions { t.Fatalf("health failed: %+v", health) }
   // Exercise replacement's strict read of the existing oversized manifest.
   if err := writeBrainManifestAndReadme(dir, *got); err != nil { t.Fatal(err) }
   before, err := os.ReadFile(filepath.Join(dir, exportManifestFileName)); if err != nil { t.Fatal(err) }
   got.GeneratedAt = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
   if err := writeBrainManifestAndReadme(dir, *got); err == nil { t.Fatal("invalid time must fail encoding") }
   after, err := os.ReadFile(filepath.Join(dir, exportManifestFileName)); if err != nil { t.Fatal(err) }
   if !bytes.Equal(before, after) { t.Fatal("failed operation changed previous manifest") }
   if _, err := loadBrainManifest(dir); err != nil { t.Fatal(err) }
  })
 }
}

func TestBrainManifestDecoderCompatibility(t *testing.T) {
 for _, tc := range []struct{name, body, code string}{
  {"v1", `{"schema_version":1}`, ""},
  {"v2", `{"schema_version":2}`, ""},
  {"v3", `{"schema_version":3}`, ""},
  {"unknown", `{"schema_version":3,"future":{"nested":true}}`, ""},
  {"empty", ``, memoryErrStateCorrupt},
  {"malformed", `{"schema_version":3, broken}`, memoryErrStateCorrupt},
  {"truncated", `{"schema_version":3,"sessions":[`, memoryErrStateCorrupt},
  {"trailing-json", `{"schema_version":3} {}`, memoryErrStateCorrupt},
  {"trailing-garbage", `{"schema_version":3} garbage`, memoryErrStateCorrupt},
  {"missing-version", `{}`, memoryErrUnsupportedVersion},
  {"newer", `{"schema_version":4,"future":true}`, memoryErrUnsupportedVersion},
  {"older", `{"schema_version":-1}`, memoryErrUnsupportedVersion},
 } {
  t.Run(tc.name, func(t *testing.T) {
   dir := writeTestManifest(t, tc.body)
   _, err := loadBrainManifest(dir)
   _, health, issue := inspectBrainManifestHealth(dir)
   if tc.code == "" {
    if err != nil || issue != nil || health.State != "current" { t.Fatalf("read=%v health=%+v", err, health) }
   } else {
    if err == nil || !strings.Contains(err.Error(), tc.code) || issue == nil || health.ErrorCode != tc.code { t.Fatalf("read=%v health=%+v", err, health) }
    if err := writeBrainManifestAndReadme(dir, exportManifest{}); err == nil { t.Fatal("writer must refuse invalid existing state") }
    after, _ := os.ReadFile(filepath.Join(dir, exportManifestFileName))
    if string(after) != tc.body { t.Fatal("failed rewrite changed original") }
   }
  })
 }
}

func TestBrainManifestReaderKeepsFileProtections(t *testing.T) {
 for _, kind := range []string{"directory", "symlink", "hardlink"} {
  t.Run(kind, func(t *testing.T) {
   dir := t.TempDir(); path := filepath.Join(dir, exportManifestFileName)
   target := filepath.Join(t.TempDir(), "target.json")
   if err := os.WriteFile(target, []byte(`{"schema_version":3}`), 0600); err != nil { t.Fatal(err) }
   var err error
   switch kind { case "directory": err=os.Mkdir(path,0700); case "symlink": err=os.Symlink(target,path); case "hardlink": err=os.Link(target,path) }
   if err != nil { t.Fatal(err) }
   if _, err := loadBrainManifest(dir); err == nil || !strings.Contains(err.Error(),memoryErrStateUnsafe) { t.Fatalf("unsafe read: %v",err) }
   _, health, _ := inspectBrainManifestHealth(dir)
   if health.State != "unsafe" { t.Fatalf("health: %+v",health) }
  })
 }
}
