   opts:=Options{StateDir:t.TempDir(),ConfigDir:t.TempDir(),DataDir:t.TempDir()}
   dir:=filepath.Join(opts.DataDir,"repos",localKey(canonical));if err:=os.MkdirAll(dir,0700);err!=nil {t.Fatal(err)}
   if err:=os.WriteFile(filepath.Join(dir,"manifest.json"),[]byte(body),0600);err!=nil {t.Fatal(err)}
   if _,err:=repositoryBrain(repo,opts);err==nil {t.Fatal("invalid manifest accepted")}
  })
 }
}
