package agentsetup

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

// Options is a test seam and supports explicit Brain store roots. The normal
// path calls ONLY entire plugin list, never a plugin command to detect availability.
type Options struct {
	ListPlugins                  func() (string, error)
	StateDir, ConfigDir, DataDir string
}

func Preview(repo, product string, opts Options) (string, error) {
	if product != "graph" && product != "brain" {
		return "", fmt.Errorf("unknown product %q", product)
	}
	standalone := GraphGuide
	if product == "brain" {
		standalone = BrainGuide()
	}
	if repo == "" {
		return standalone, nil
	}
	list := opts.ListPlugins
	if list == nil {
		list = pluginList
	}
	raw, err := list()
	// The host is optional for directly invoked standalone binaries. Only an
	// absent executable permits fallback: a broken host or malformed listing
	// must not silently downgrade an existing coordinated workflow.
	if errors.Is(err, exec.ErrNotFound) {
		return standalone, nil
	}
	if err != nil {
		return "", fmt.Errorf("read entire plugin list: %w", err)
	}
	installed, err := parsePluginList(raw)
	if err != nil {
		return "", err
	}
	if product == "brain" {
		if installed["graph"] {
			return CombinedGuide, nil
		}
		return BrainGuide(), nil
	}
	if installed["brain"] {
		exists, err := repositoryBrain(repo, opts)
		if err != nil {
			return "", err
		}
		if exists {
			return CombinedGuide, nil
		}
	}
	return GraphGuide, nil
}

type limitedBuffer struct {
	bytes.Buffer
	limit int
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	if b.Len()+len(p) > b.limit {
		return 0, fmt.Errorf("command output exceeds limit")
	}
	return b.Buffer.Write(p)
}
func localCommand(repo, name string, args ...string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Dir = repo
	cmd.Env = os.Environ()
	if name == "git" {
		// Match Brain's configured origin, including includes and URL rewrites.
		// remote get-url reads configuration only: no transport, filters, or hooks.
		// A caller's Git worktree overrides must not redirect the explicit target.
		cmd.Env = nil
		for _, entry := range os.Environ() {
			key, _, _ := strings.Cut(entry, "=")
			switch key {
			case "GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES":
				continue
			}
			cmd.Env = append(cmd.Env, entry)
		}
	}
	cmd.WaitDelay = 2 * time.Second

	out, stderr := &limitedBuffer{limit: 1 << 20}, &limitedBuffer{limit: 64 << 10}
	cmd.Stdout = out
	cmd.Stderr = stderr
	err := cmd.Run()
	if err != nil {
		return "", fmt.Errorf("%s: %w: %s", name, err, strings.TrimSpace(stderr.String()))
	}
	return out.String(), nil

// seedManifestMaxUncoveredCommits bounds the per-commit gap list that is copied
// into the brain manifest.
//
// The list had no bound at all, and it is one record per commit that carries no
